"""Render the exact chart CSVs to PNG and save their interactive Vega-Lite specifications."""
from pathlib import Path
import json,shutil,sys
import vl_convert as vlc
R=Path(__file__).resolve().parents[1];C=R/'charts';C.mkdir(exist_ok=True)
E=R/'expected' if (R/'expected').exists() else R/'data/expected'
base={'$schema':'https://vega.github.io/schema/vega-lite/v5.json','background':'#fbfaf7','config':{'font':'Arial','axis':{'labelColor':'#26333d','titleColor':'#26333d','gridColor':'#e2e1dc'},'view':{'stroke':None},'legend':{'orient':'bottom','title':None}}}
def save(name,spec):
 spec={**base,**spec};(C/(name+'.vl.json')).write_text(json.dumps(spec,indent=2));shutil.copy2(E/(name+'.csv'),C/(name+'.csv'))
 render=json.loads(json.dumps(spec));render['data']={'values':__import__('csv').DictReader((C/(name+'.csv')).open())};render['data']['values']=list(render['data']['values'])
 # CSV readers supply strings, unlike Vega's CSV auto-typing. Convert quantitative fields for PNG parity.
 for row in render['data']['values']:
  for k,v in list(row.items()):
   try:row[k]=float(v)
   except ValueError:pass
 (C/(name+'.png')).write_bytes(vlc.vegalite_to_png(render,scale=2))
 print(name,'PNG', (C/(name+'.png')).stat().st_size)
palette=['#176b99','#b76810','#247a60','#8a5b32','#858b91','#a4b5bf']
save('1-book-frequency',{'width':650,'height':280,'title':{'text':'Literally became more frequent in books','subtitle':'Unsmoothed annual frequency, 2019 Google Books datasets; case-insensitive'},'data':{'url':'charts/1-book-frequency.csv'},'params':[{'name':'series','select':{'type':'point','fields':['corpus']},'bind':'legend'}],'mark':{'type':'line','strokeWidth':1.5},'encoding':{'x':{'field':'year','type':'quantitative','title':'Publication year','axis':{'format':'d'}},'y':{'field':'per_million_words','type':'quantitative','title':'Occurrences per million words'},'color':{'field':'corpus','type':'nominal','scale':{'range':palette[:3]}},'opacity':{'condition':{'param':'series','value':1},'value':0.12},'tooltip':[{'field':'corpus'},{'field':'year','format':'d'},{'field':'per_million_words','format':'.2f'}]}})
save('2-reading-distribution',{'width':650,'height':180,'title':{'text':'Factual readings form the largest group','subtitle':'60 random occurrences per corpus; agent annotation, with uncertain cases retained'},'data':{'url':'charts/2-reading-distribution.csv'},'params':[{'name':'readings','select':{'type':'point','fields':['reading']},'bind':'legend'}],'mark':'bar','encoding':{'y':{'field':'corpus','type':'nominal','title':None,'sort':['BNC1994','Spoken BNC2014','enTenTen21']},'x':{'field':'count','type':'quantitative','stack':'zero','title':'Occurrences out of 60'},'color':{'field':'reading','type':'nominal','sort':['factual','figurative','metalinguistic','dual','uncertain','mention_or_error'],'scale':{'domain':['factual','figurative','metalinguistic','dual','uncertain','mention_or_error'],'range':palette},'legend':{'labelExpr':"datum.label === 'mention_or_error' ? 'Mention or error' : datum.label"}},'order':{'field':'reading'},'opacity':{'condition':{'param':'readings','value':1},'value':0.15},'tooltip':[{'field':'corpus'},{'field':'reading'},{'field':'count'},{'field':'percent','format':'.1f'}]}})
save('3-function-comparison',{'data':{'url':'charts/3-function-comparison.csv'},'title':{'text':'Emphasis and nonliteral meaning are different counts','subtitle':'Points with nominal 95% Wilson intervals; 60 occurrences per corpus'},'facet':{'row':{'field':'measure','type':'nominal','title':None,'header':{'labelOrient':'top','labelAnchor':'start'}}},'spec':{'width':550,'height':100,'encoding':{'y':{'field':'corpus','type':'nominal','title':None,'sort':['BNC1994','Spoken BNC2014','enTenTen21']},'color':{'field':'measure','type':'nominal','scale':{'range':['#176b99','#b76810']},'legend':None},'tooltip':[{'field':'corpus'},{'field':'measure'},{'field':'count'},{'field':'percent','format':'.1f'},{'field':'lower','format':'.1f'},{'field':'upper','format':'.1f'}]},'layer':[{'mark':{'type':'rule','strokeWidth':2},'encoding':{'x':{'field':'lower','type':'quantitative','scale':{'domain':[0,100]},'title':'Percentage of all sampled occurrences'},'x2':{'field':'upper'}}},{'mark':{'type':'point','filled':True,'size':85},'encoding':{'x':{'field':'percent','type':'quantitative','scale':{'domain':[0,100]},'title':'Percentage of all sampled occurrences'}}}]}})
save('4-book-contexts',{'title':{'text':'Phrase frequencies are not sense frequencies','subtitle':'English books, 2019 dataset; each panel uses its own vertical scale'},'data':{'url':'charts/4-book-contexts.csv'},'facet':{'field':'construction','type':'nominal','title':None,'header':{'labelExpr':"datum.label === 'literally _ADJ_' ? 'literally + adjective' : datum.label"}},'columns':2,'spec':{'width':285,'height':150,'mark':{'type':'line','color':'#176b99'},'encoding':{'x':{'field':'year','type':'quantitative','axis':{'format':'d'},'title':'Year'},'y':{'field':'per_million_bigrams','type':'quantitative','title':'Per million bigrams'},'tooltip':[{'field':'construction'},{'field':'year','format':'d'},{'field':'per_million_bigrams','format':'.4f'}]}},'resolve':{'scale':{'y':'independent'}}})
